using namespace std;

class Solution {
public:
    int maxProfit(vector<int>& inventory, int orders) {
        long long MOD = 1e9 + 7;
        int lo = 0, hi = 0;
        for (int x : inventory) hi = max(hi, x);
        int threshold = 0;
        while (lo <= hi) {
            int mid = lo + (hi - lo) / 2;
            long long total_sold = 0;
            for (int x : inventory) {
                if (x > mid) total_sold += (x - mid);
            }
            if (total_sold <= orders) {
                threshold = mid;
                hi = mid - 1;
            } else {
                lo = mid + 1;
            }
        }
        long long profit = 0;
        long long sold = 0;
        for (int x : inventory) {
            if (x > threshold) {
                long long cnt = x - threshold;
                long long sum = ((long long)(threshold + 1 + x) * cnt) / 2;
                profit = (profit + sum) % MOD;
                sold += cnt;
            }
        }
        long long rem = orders - sold;
        profit = (profit + rem * threshold) % MOD;
        return profit;
    }
};

class Solution {
    public int maxProfit(int[] inventory, int orders) {
        long MOD = 1000000007L;
        int lo = 0, hi = 0;
        for (int x : inventory) hi = Math.max(hi, x);
        int threshold = 0;
        while (lo <= hi) {
            int mid = lo + (hi - lo) / 2;
            long totalSold = 0;
            for (int x : inventory) {
                if (x > mid) totalSold += (x - mid);
            }
            if (totalSold <= orders) {
                threshold = mid;
                hi = mid - 1;
            } else {
                lo = mid + 1;
            }
        }
        long profit = 0;
        long sold = 0;
        for (int x : inventory) {
            if (x > threshold) {
                long cnt = x - threshold;
                long sum = ((long)(threshold + 1 + x) * cnt) / 2;
                profit = (profit + sum) % MOD;
                sold += cnt;
            }
        }
        long rem = orders - sold;
        profit = (profit + rem * threshold) % MOD;
        return (int)profit;
    }
}

