var maxProfit = function(inventory, orders) {
    const MOD = 1000000007n;
    let lo = 0n, hi = 0n;
    for (const x of inventory) {
        const bx = BigInt(x);
        if (bx > hi) hi = bx;
    }
    const bOrders = BigInt(orders);
    let threshold = 0n;
    while (lo <= hi) {
        const mid = (lo + hi) / 2n;
        let totalSold = 0n;
        for (const x of inventory) {
            const bx = BigInt(x);
            if (bx > mid) totalSold += (bx - mid);
        }
        if (totalSold <= bOrders) {
            threshold = mid;
            hi = mid - 1n;
        } else {
            lo = mid + 1n;
        }
    }
    let profit = 0n;
    let sold = 0n;
    for (const x of inventory) {
        const bx = BigInt(x);
        if (bx > threshold) {
            const cnt = bx - threshold;
            const sum = ((threshold + 1n + bx) * cnt) / 2n;
            profit = (profit + sum) % MOD;
            sold += cnt;
        }
    }
    const rem = bOrders - sold;
    profit = (profit + rem * threshold) % MOD;
    return Number(profit);
};
